32	//
33	// ***************************************************************************
34	// ***************************************************************************
35	
36	`timescale 1ns/100ps
37	
38	module spi_engine_execution #(
39	
40	  parameter NUM_OF_CS = 1,
41	  parameter DEFAULT_SPI_CFG = 0,
42	  parameter DEFAULT_CLK_DIV = 0,
43	  parameter DATA_WIDTH = 8,                   // Valid data widths values are 8/16/24/32
44	  parameter NUM_OF_SDIO = 1,
45	  parameter [0:0] SDO_DEFAULT = 1'b0,
46	  parameter ECHO_SCLK = 0,
47	  parameter [1:0] SDI_DELAY = 2'b00
48	) (
49	  input clk,
50	  input resetn,
51	  input s_offload_active,
52	
53	  output cmd_ready,
54	  input cmd_valid,
55	  input [15:0] cmd,
56	
57	  input sdo_data_valid,
58	  output sdo_data_ready,
59	  input [(DATA_WIDTH)-1:0] sdo_data,
60	
61	  input sdi_data_ready,
62	  output sdi_data_valid,
63	  output [(NUM_OF_SDIO * DATA_WIDTH)-1:0] sdi_data,
64	
65	  input sync_ready,
66	  output reg sync_valid,
67	  output [7:0] sync,
68	
69	  input echo_sclk,
70	  output reg sclk,
71	  output reg [NUM_OF_SDIO-1:0] sdo,
72	  output reg sdo_t,
73	  input [NUM_OF_SDIO-1:0] sdi,
74	  output reg [NUM_OF_CS-1:0] cs,
75	  output reg three_wire
76	);
77	
78	  localparam CMD_TRANSFER = 3'b000;
79	  localparam CMD_CHIPSELECT = 3'b001;
80	  localparam CMD_WRITE = 3'b010;
81	  localparam CMD_MISC = 3'b011;
82	  localparam CMD_CS_INV = 3'b100;
83	
84	  localparam MISC_SYNC = 1'b0;
85	  localparam MISC_SLEEP = 1'b1;
86	
87	  localparam REG_CLK_DIV = 3'b000;
88	  localparam REG_CONFIG = 3'b001;
89	  localparam REG_WORD_LENGTH = 3'b010;
90	  localparam REG_SDI_LANE_CONFIG = 3'b011;
91	  localparam REG_SDO_LANE_CONFIG = 3'b100;
92	  localparam ALL_ACTIVE_LANE_MASK = (2 ** NUM_OF_SDIO) - 1; //by default all lanes are enabled
93	
94	  localparam BIT_COUNTER_WIDTH =  DATA_WIDTH > 16 ? 5 :
95	                                  DATA_WIDTH > 8  ? 4 : 3;
96	
97	  reg sclk_int = 1'b0;
98	  reg sdo_t_int = 1'b0;
99	
100	  reg idle;
101	
102	  reg [7:0] clk_div_counter = 'h00;
103	  reg clk_div_last;
104	
105	  reg [7:0] sleep_counter;
106	  reg [(BIT_COUNTER_WIDTH-1):0] bit_counter;
107	  reg [7:0] transfer_counter;
108	  reg [7:0] echo_transfer_counter;
109	  reg ntx_rx;
110	  reg sleep_counter_increment;
111	
112	  reg trigger = 1'b0;
113	  reg wait_for_io = 1'b0;
114	  reg transfer_active = 1'b0;
115	  reg transfer_done = 1'b0;
116	
117	  reg last_transfer;
118	  reg echo_last_transfer;
119	  reg [7:0] word_length = DATA_WIDTH;
120	  reg [7:0] last_bit_count = DATA_WIDTH-1;
121	  reg [7:0] latch_last_bit_count = DATA_WIDTH-2;
122	  reg [7:0] left_aligned = 8'b0;
123	  // sdi_lane_mask: Stores the SDI lane configuration from REG_SDI_LANE_CONFIG
124	  // write commands (cmd[15:8] == 8'h23). While not directly used in this module,
125	  // the same command is intercepted by axi_spi_engine to configure sdi_fifo_tkeep_int,
126	  // which controls valid lanes in the SDI asymmetric FIFO (util_axis_fifo_asym).
127	  reg [7:0] sdi_lane_mask =  ALL_ACTIVE_LANE_MASK;
128	  reg [7:0] sdo_lane_mask =  ALL_ACTIVE_LANE_MASK;
129	
130	  reg cpha = DEFAULT_SPI_CFG[0];
131	  reg cpol = DEFAULT_SPI_CFG[1];
132	  reg [7:0] clk_div = DEFAULT_CLK_DIV;
133	  reg sdo_idle_state = SDO_DEFAULT;
134	
135	  reg [NUM_OF_CS-1:0] cs_inv_mask_reg = 'h0;
136	
137	  reg sdo_enabled = 1'b0;
138	  reg sdi_enabled = 1'b0;
139	  reg pending_sdi_data_valid = 1'b0;
140	  wire sdo_enabled_io;
141	
142	  wire [NUM_OF_SDIO-1:0] sdo_int_s;
143	
144	  wire last_bit;
145	  wire echo_last_bit;
146	  reg first_bit;
147	  wire end_of_word;
148	
149	  //command decoder
150	  wire [2:0] inst                 = cmd[14:12];
151	  wire       exec_cmd             = cmd_ready && cmd_valid;
152	  wire       exec_transfer_cmd    = exec_cmd && inst == CMD_TRANSFER;
153	  wire       exec_chipselect_cmd  = exec_cmd && inst == CMD_CHIPSELECT;
154	  wire       exec_write_cmd       = exec_cmd && inst == CMD_WRITE;
155	  wire       exec_misc_cmd        = exec_cmd && inst == CMD_MISC;
156	  wire       exec_cs_inv_cmd      = exec_cmd && inst == CMD_CS_INV;
157	  wire       exec_sync_cmd        = exec_misc_cmd && cmd[8] == MISC_SYNC;
158	
159	  reg [15:0] cmd_d1;
160	  reg [ 7:0] cmd_d1_time;
161	  reg [ 1:0] cmd_d1_delay;
162	  reg [ 2:0] cmd_d1_instr;
163	  reg        cmd_d1_sleep_instr;
164	  reg        exec_transfer_cmd_reg = 1'b0; //avoid comparison in the shiftreg
165	  reg        exec_sdo_lane_config_reg = 1'b0; //avoid comparison in the shiftreg data assemble
166	  reg        exec_chipselect_cmd_reg = 1'b0; //avoid comparison cs_gen
167	  reg        cmd_d1_time_is_zero;
168	
169	  wire trigger_tx;
170	  wire trigger_rx;
171	
172	  reg sleep_counter_compare;
173	  reg cs_sleep_counter_compare;
174	  reg cs_sleep_early_exit;
175	  reg cs_sleep_repeat;
176	  reg cs_activate;
177	
178	  wire io_ready1;
179	  wire io_ready2;
180	
181	  wire sdo_io_ready;
182	
183	  (* direct_enable = "yes" *) wire cs_gen;
184	
185	  spi_engine_execution_shiftreg #(
186	    .DEFAULT_SPI_CFG(DEFAULT_SPI_CFG),
187	    .DATA_WIDTH(DATA_WIDTH),
188	    .NUM_OF_SDIO(NUM_OF_SDIO),
189	    .SDI_DELAY(SDI_DELAY),
190	    .ECHO_SCLK(ECHO_SCLK)
191	  ) shiftreg (
192	    .clk(clk),
193	    .resetn(resetn),
194	    .s_offload_active(s_offload_active),
195	    .sdi(sdi),
196	    .sdo_int(sdo_int_s),
197	    .echo_sclk(echo_sclk),
198	    .sdo_data(sdo_data),
199	    .sdo_data_valid(sdo_data_valid),
200	    .sdo_data_ready(sdo_data_ready),
201	    .sdi_data(sdi_data),
202	    .sdi_data_valid(sdi_data_valid),
203	    .sdi_data_ready(sdi_data_ready),
204	    .sdo_enabled(sdo_enabled),
205	    .sdi_enabled(sdi_enabled),
206	    .current_cmd(cmd_d1),
207	    .exec_cmd(exec_transfer_cmd_reg),
208	    .exec_sdo_lane_cmd(exec_sdo_lane_config_reg),
209	    .sdo_idle_state(sdo_idle_state),
210	    .left_aligned(left_aligned),
211	    .word_length(word_length),
212	    .last_bit_count (last_bit_count),
213	    .latch_last_bit_count (latch_last_bit_count),
214	    .sdo_lane_mask(sdo_lane_mask),
215	    .sdo_io_ready(sdo_io_ready),
216	    .echo_last_bit(echo_last_bit),
217	    .transfer_active(transfer_active),
218	    .trigger_tx(trigger_tx),
219	    .trigger_rx(trigger_rx),
220	    .first_bit(first_bit),
221	    .cs_activate(cs_activate));
222	
223	  assign cs_gen = exec_chipselect_cmd_reg
224	                  && (cs_sleep_counter_compare || cs_sleep_early_exit)
225	                  && (~cs_sleep_repeat) && (~idle);
226	  assign cmd_ready = idle;
227	
228	  always @(posedge clk) begin
229	    if (exec_transfer_cmd) begin
230	      sdo_enabled <= cmd[8];
231	      sdi_enabled <= cmd[9];
232	    end
233	  end
234	  assign sdo_enabled_io = (exec_transfer_cmd) ? cmd[8] : sdo_enabled;
235	
236	  always @(posedge clk) begin
237	    if (exec_cmd) begin
238	      cmd_d1                   <= cmd;
239	      cmd_d1_instr             <= cmd[14:12];
240	      cmd_d1_delay             <= cmd[9:8];
241	      cmd_d1_sleep_instr       <= cmd[8];
242	      cmd_d1_time              <= cmd[7:0];
243	      cs_sleep_early_exit      <= ~|cmd[9:8];
244	      cmd_d1_time_is_zero      <= ~|cmd[7:0];
245	      exec_transfer_cmd_reg    <= (inst == CMD_TRANSFER);
246	      exec_chipselect_cmd_reg  <= (inst == CMD_CHIPSELECT);
247	      exec_sdo_lane_config_reg <= (inst == CMD_WRITE) && (cmd[10:8] == REG_SDO_LANE_CONFIG);
248	    end else begin
249	      exec_sdo_lane_config_reg <= 1'b0;
250	      sleep_counter_compare <= sleep_counter == cmd_d1_time && clk_div_last && sleep_counter_increment;
251	    end
252	  end
253	
254	  // Load the interface configurations from the 'Configuration Write'
255	  // instruction
256	  always @(posedge clk) begin
257	    if (!resetn) begin
258	      cpha           <= DEFAULT_SPI_CFG[0];
259	      cpol           <= DEFAULT_SPI_CFG[1];
260	      three_wire     <= DEFAULT_SPI_CFG[2];
261	      sdo_idle_state <= SDO_DEFAULT;
262	      clk_div        <= DEFAULT_CLK_DIV;
263	      word_length    <= DATA_WIDTH;
264	      left_aligned   <= 0;
265	      sdi_lane_mask  <= ALL_ACTIVE_LANE_MASK;
266	      sdo_lane_mask  <= ALL_ACTIVE_LANE_MASK;
267	    end else begin
268	      if (exec_write_cmd) begin
269	        case (cmd[10:8])
270	          REG_CLK_DIV         : begin
271	                                  clk_div        <= cmd[7:0];
272	                                end
273	          REG_CONFIG          : begin
274	                                  cpha           <= cmd[0];
275	                                  cpol           <= cmd[1];
276	                                  three_wire     <= cmd[2];
277	                                  sdo_idle_state <= cmd[3];
278	                                end
279	          REG_WORD_LENGTH     : begin
280	                                  // the max value of this reg must be DATA_WIDTH
281	                                  word_length    <= cmd[7:0];
282	                                  // needed 1 cycle before transfer_active goes high
283	                                  left_aligned   <= DATA_WIDTH - cmd[7:0];
284	                                end
285	          REG_SDI_LANE_CONFIG : begin
286	                                  sdi_lane_mask  <= cmd[7:0];
287	                                end
288	          REG_SDO_LANE_CONFIG : begin
289	                                  //max number of spi lanes is 8
290	                                  sdo_lane_mask  <= cmd[7:0];
291	                                end
292	        endcase
293	      end
294	    end
295	  end
296	
297	  always @(posedge clk) begin
298	    // we can calculate this from word_length (instead of cmd), with an extra cycle delay
299	    // because even in the worst case (transfer after config), we still have another cycle before using it
300	    last_bit_count       <= word_length - 1; // needed when transfer_active goes high
301	    latch_last_bit_count <= word_length - 2;
302	  end
303	
304	  always @(posedge clk) begin
305	    if (~|clk_div_counter || idle || wait_for_io) begin
306	      clk_div_counter <= clk_div;
307	      trigger         <= 1'b1;
308	    end else begin
309	      clk_div_counter <= clk_div_counter - 1'b1;
310	      trigger         <= 1'b0;
311	    end
312	    clk_div_last <= ((~clk_div_last && ~idle && ~wait_for_io && clk_div_counter == 8'h1) || ~|clk_div);
313	  end
314	
315	  assign trigger_tx = trigger && ~ntx_rx;
316	  assign trigger_rx = trigger && ntx_rx;
317	
318	  always @(posedge clk) begin
319	    if (!resetn) begin
320	      cs_sleep_repeat <= 1'b0;
321	    end else begin
322	      if (idle) begin
323	        cs_sleep_repeat <= 1'b0;
324	      end else if (cs_sleep_counter_compare && exec_chipselect_cmd_reg) begin
325	        cs_sleep_repeat <= !cs_sleep_repeat;
326	      end
327	    end
328	  end
329	
330	  always @(posedge clk) begin
331	    if (idle) begin
332	      bit_counter <= 0;
333	      first_bit <= 1'b1;
334	      transfer_counter <= 0;
335	      ntx_rx  <= 1'b0;
336	      sleep_counter_increment <= 1'b0;
337	      sleep_counter <= 0;
338	      if (cmd_valid) begin
339	        cs_sleep_counter_compare <= 1'b0;
340	      end
341	    end else begin
342	      first_bit <= ((bit_counter + ntx_rx == 0) || (bit_counter == word_length-1));
343	      if (clk_div_last && ~wait_for_io) begin
344	        if (last_bit && transfer_active && ntx_rx) begin
345	          bit_counter <= 0;
346	          transfer_counter <= transfer_counter + 1;
347	          ntx_rx <= ~ntx_rx;
348	        end else begin
349	          if (transfer_active) begin
350	            bit_counter <= bit_counter + ntx_rx;
351	            ntx_rx <= ~ntx_rx;
352	          end else begin
353	            sleep_counter_increment <= ~sleep_counter_increment;
354	            sleep_counter <= sleep_counter + sleep_counter_increment;
355	            cs_sleep_counter_compare <= (sleep_counter[1:0] + sleep_counter_increment) == cmd_d1_delay;
356	          end
357	        end
358	      end
359	      if (cs_sleep_counter_compare && !cs_sleep_repeat && exec_chipselect_cmd_reg) begin
360	        sleep_counter <= 'h0;
361	        cs_sleep_counter_compare <= 1'b0;
362	      end
363	    end
364	  end
365	
366	  always @(posedge clk) begin
367	    if (sdi_enabled == 1'b1 && last_bit && trigger_rx == 1'b1) begin
368	      pending_sdi_data_valid <= 1'b1;
369	    end else if (sdi_data_ready == 1'b1) begin
370	      pending_sdi_data_valid <= 1'b0;
371	    end
372	  end
373	
374	  always @(posedge clk) begin
375	    if (!resetn) begin
376	      idle <= 1'b1;
377	    end else begin
378	      if (exec_transfer_cmd || exec_chipselect_cmd || exec_misc_cmd) begin
379	        idle <= 1'b0;
380	      end else begin
381	        case (cmd_d1_instr)
382	        CMD_TRANSFER: begin
383	          if (transfer_done)
384	            idle <= 1'b1;
385	        end
386	        CMD_CHIPSELECT: begin
387	          if ((cs_sleep_counter_compare && cs_sleep_repeat) || cs_sleep_early_exit)
388	            idle <= 1'b1;
389	        end
390	        CMD_MISC: begin
391	          case (cmd_d1_sleep_instr)
392	          MISC_SLEEP: begin
393	            if (sleep_counter_compare)
394	              idle <= 1'b1;
395	          end
396	          MISC_SYNC: begin
397	            if (sync_ready)
398	              idle <= 1'b1;
399	          end
400	          endcase
401	        end
402	        endcase
403	      end
404	    end
405	  end
406	
407	  always @(posedge clk ) begin
408	    if (!resetn) begin
409	      cs_inv_mask_reg <= 0;
410	    end else begin
411	      if (exec_cs_inv_cmd) begin
412	        cs_inv_mask_reg <= cmd[NUM_OF_CS-1:0];
413	      end
414	    end
415	  end
416	
417	  always @(posedge clk) begin
418	    if (!resetn) begin
419	      cs <= 'hff;
420	    end else if (cs_gen) begin
421	      cs <= cmd_d1[NUM_OF_CS-1:0]^cs_inv_mask_reg[NUM_OF_CS-1:0];
422	    end
423	  end
424	
425	  always @(posedge clk) begin
426	    if (!resetn) begin
427	      sync_valid <= 1'b0;
428	    end else begin
429	      if (exec_sync_cmd) begin
430	        sync_valid <= 1'b1;
431	      end else if (sync_ready) begin
432	        sync_valid <= 1'b0;
433	      end
434	    end
435	  end
436	
437	  assign sync = cmd_d1[7:0];
438	
439	  // The sdi_data_valid signal has inherent delays due to ECHO_SCLK and SCLK timing.
440	  // To handle backpressure, pending_sdi_data_valid is asserted when the last bit
441	  // is received and remains high until sdi_data_ready acknowledges the data.
442	  assign io_ready1 =  (pending_sdi_data_valid == 1'b0 || sdi_data_ready == 1'b1) &&
443	                      (sdo_enabled_io == 1'b0 || sdo_io_ready == 1'b1);
444	
445	  assign io_ready2 = (sdi_enabled == 1'b0 || sdi_data_ready == 1'b1) &&
446	                     (sdo_enabled_io == 1'b0 || last_transfer == 1'b1 || sdo_io_ready == 1'b1);
447	
448	  always @(posedge clk) begin
449	    if (idle) begin
450	      last_transfer <= 1'b0;
451	    end else if (trigger_tx && transfer_active) begin
452	      last_transfer <= (transfer_counter == cmd_d1[7:0]);
453	    end
454	  end
455	
456	  always @(posedge clk) begin
457	    if (!resetn || idle) begin
458	      echo_last_transfer    <= 1'b0;
459	    end else begin
460	      if (exec_transfer_cmd_reg && cmd_d1_time_is_zero) begin
461	        echo_last_transfer    <= 1'b1;
462	      end else if (echo_last_bit) begin
463	        if (echo_transfer_counter + 1 == cmd_d1[7:0]) begin
464	          echo_last_transfer    <= 1'b1;
465	        end else begin
466	          echo_last_transfer    <= 1'b0;
467	        end
468	      end
469	    end
470	  end
471	
472	  always @(posedge clk ) begin
473	    if (!resetn || idle) begin
474	      echo_transfer_counter <= 0;
475	    end else begin
476	      if (echo_last_bit) begin
477	        echo_transfer_counter <= echo_transfer_counter + 1;
478	      end
479	    end
480	  end
481	
482	  always @(posedge clk) begin
483	    if (!resetn) begin
484	      transfer_active <= 1'b0;
485	      wait_for_io <= 1'b0;
486	    end else begin
487	      if (exec_transfer_cmd) begin
488	        wait_for_io <= ~io_ready1;
489	        transfer_active <= io_ready1;
490	      end else if (wait_for_io && io_ready1) begin
491	        wait_for_io <= 1'b0;
492	        transfer_active <= ~last_transfer;
493	      end else if (transfer_active == 1'b1 && end_of_word == 1'b1) begin
494	        if (last_transfer || ~io_ready2) begin
495	          transfer_active <= 1'b0;
496	        if (~io_ready2)
497	          wait_for_io <= 1'b1;
498	        end
499	      end else if (idle == 1'b1) begin
500	        wait_for_io <= 1'b0;
501	        transfer_active <= 1'b0;
502	      end
503	    end
504	  end
505	
506	  always @(posedge clk ) begin
507	    if (!resetn) begin
508	      transfer_done <= 1'b0;
509	    end else begin
510	      if (ECHO_SCLK) begin
511	        transfer_done <= echo_last_bit && echo_last_transfer;
512	      end else begin
513	        transfer_done <= (wait_for_io && io_ready1 && last_transfer) || (~wait_for_io && transfer_active && end_of_word && last_transfer);
514	      end
515	    end
516	  end
517	
518	  always @(posedge clk) begin
519	    if (transfer_active || wait_for_io)
520	    begin
521	      sdo_t_int <= ~sdo_enabled;
522	    end else begin
523	      sdo_t_int <= 1'b1;
524	    end
525	  end
526	
527	  always @(posedge clk) begin
528	    if (!resetn) begin // set cs_activate during reset for a cycle to clear shift reg
529	      cs_activate <= 1;
530	    end else begin
531	      cs_activate <= ~(&cmd_d1[NUM_OF_CS-1:0]) & cs_gen;
532	    end
533	  end
534	
535	  // end_of_word will signal the end of a transaction, pushing the command
536	  // stream execution to the next command. end_of_word in normal mode can be
537	  // generated using the global bit_counter
538	  assign last_bit = (bit_counter == last_bit_count);
539	  assign end_of_word = last_bit && ntx_rx && clk_div_last;
540	
541	  always @(posedge clk) begin
542	    if (transfer_active) begin
543	      sclk_int <= cpol ^ cpha ^ ntx_rx;
544	    end else begin
545	      sclk_int <= cpol;
546	    end
547	  end
548	
549	  // Additional register stage to improve timing
550	  always @(posedge clk) begin
551	    sclk <= sclk_int;
552	    sdo <= sdo_int_s;
553	    sdo_t <= sdo_t_int;
554	  end
555	
556	endmodule
557

